import { readFileSync, writeFileSync } from "node:fs";
import { join } from "node:path";

const packageRoot = join(import.meta.dir, "..");
const sourcePath = join(packageRoot, "theme", "tokens.css");
const themePath = join(packageRoot, "theme", "theme.css");
const scopedOutputPath = join(packageRoot, "theme", "scoped-tokens.css");
const componentThemeOutputPath = join(
	packageRoot,
	"theme",
	"component-theme.css",
);
const checkOnly = process.argv.includes("--check");
const scopedHeader = `/*
 * Generated by scripts/generate-theme.ts from theme/tokens.css.
 * Edit tokens.css, then run \`bun run generate:theme\`.
 */

`;
const componentThemeHeader = `/*
 * Generated by scripts/generate-theme.ts from theme/tokens.css and
 * theme/theme.css. Edit those sources, then run \`bun run generate:theme\`.
 *
 * These package-specific names keep embedded components from changing generic
 * host utilities such as bg-background, text-foreground, and rounded-lg.
 */

`;

function replaceSelector(
	source: string,
	selector: string,
	replacement: string,
): string {
	const ruleStart = `${selector} {`;
	if (source.split(ruleStart).length !== 2) {
		throw new Error(`${ruleStart} must occur exactly once in ${sourcePath}`);
	}
	return source.replace(ruleStart, `${replacement} {`);
}

function readBlock(source: string, selector: string): string {
	const start = source.indexOf(`${selector} {`);
	if (start < 0) throw new Error(`Missing ${selector} block`);
	const bodyStart = source.indexOf("{", start) + 1;
	let depth = 1;
	for (let index = bodyStart; index < source.length; index += 1) {
		if (source[index] === "{") depth += 1;
		if (source[index] === "}") depth -= 1;
		if (depth === 0) return source.slice(bodyStart, index);
	}
	throw new Error(`Unclosed ${selector} block`);
}

function declarationNames(source: string): string[] {
	return Array.from(
		source.matchAll(/(^|\n)\s*(--[a-z0-9-]+)\s*:/g),
		(match) => match[2],
	);
}

function componentThemeName(rawName: string): string {
	if (rawName.startsWith("--font-weight-")) {
		return rawName.replace("--font-weight-", "--font-weight-cline-ui-");
	}
	if (rawName.startsWith("--font-")) {
		return rawName.replace("--font-", "--font-cline-ui-");
	}
	if (rawName.startsWith("--text-")) {
		const [size, ...companions] = rawName.slice("--text-".length).split("--");
		return `--text-cline-ui-${size}${companions.length ? `--${companions.join("--")}` : ""}`;
	}
	throw new Error(`Unsupported component typography token ${rawName}`);
}

function mappedDeclaration(mappedName: string, rawName: string): string {
	const declaration = `\t${mappedName}: var(${rawName});`;
	return declaration.length < 80
		? declaration
		: `\t${mappedName}: var(\n\t\t${rawName}\n\t);`;
}

function generateComponentTheme(tokens: string, theme: string): string {
	const themeNames = declarationNames(readBlock(theme, "@theme inline"));
	const colorNames = themeNames.filter((name) => name.startsWith("--color-"));
	const radiusNames = themeNames.filter((name) => name.startsWith("--radius-"));
	const typographyNames = declarationNames(readBlock(tokens, ":root")).filter(
		(name) =>
			name.startsWith("--font-") ||
			name.startsWith("--font-weight-") ||
			name.startsWith("--text-"),
	);

	const declarations = [
		...colorNames.map((name) => {
			const rawName = name.replace("--color-", "--");
			return mappedDeclaration(
				name.replace("--color-", "--color-cline-ui-"),
				rawName,
			);
		}),
		"",
		...typographyNames.map((name) =>
			mappedDeclaration(componentThemeName(name), name),
		),
		"",
		...radiusNames.map((name) =>
			mappedDeclaration(name.replace("--radius-", "--radius-cline-ui-"), name),
		),
	];

	return `${componentThemeHeader}@custom-variant cline-ui-dark (&:is(.dark *));\n\n@theme inline {\n${declarations.join("\n")}\n}\n`;
}

const source = readFileSync(sourcePath, "utf8");
const theme = readFileSync(themePath, "utf8");
const sourceWithoutHeader = source.replace(/^\/\*[\s\S]*?\*\/\s*/, "");
if (sourceWithoutHeader === source) {
	throw new Error(`${sourcePath} must start with a contract comment`);
}
const generatedScopedTokens =
	scopedHeader +
	replaceSelector(
		replaceSelector(sourceWithoutHeader, ":root", ".cline-ui-theme"),
		".dark",
		".dark .cline-ui-theme,\n.cline-ui-theme.dark",
	);
const generatedComponentTheme = generateComponentTheme(source, theme);
const outputs = [
	[scopedOutputPath, generatedScopedTokens],
	[componentThemeOutputPath, generatedComponentTheme],
] as const;

if (checkOnly) {
	for (const [outputPath, generated] of outputs) {
		if (readFileSync(outputPath, "utf8") !== generated) {
			throw new Error(`${outputPath} is out of date`);
		}
	}
	console.log("@cline/ui generated theme files are current");
} else {
	for (const [outputPath, generated] of outputs) {
		writeFileSync(outputPath, generated);
	}
	console.log("Generated @cline/ui scoped and component themes");
}
